void qlcnic_free_sw_resources ( struct qlcnic_adapter * adapter ) { struct qlcnic_recv_context * recv_ctx ; struct qlcnic_host_rds_ring * rds_ring ; int ring ; recv_ctx = adapter -> recv_ctx ; for ( ring = 0 ; ring < adapter -> max_rds_rings ; ring ++ ) { rds_ring = & recv_ctx -> rds_rings [ ring ] ; vfree ( rds_ring -> rx_buf_arr ) ; rds_ring -> rx_buf_arr = NULL ; } kfree ( recv_ctx -> rds_rings ) ; } 